CREATE TABLE schedule_resources(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),code TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('staff','room','equipment')),user_id TEXT REFERENCES users(id),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,code),UNIQUE(id,store_id),CHECK((kind='staff' AND user_id IS NOT NULL) OR (kind!='staff' AND user_id IS NULL)));
CREATE TABLE schedule_resource_versions(resource_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),sequence INTEGER NOT NULL CHECK(sequence>0),name TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(typeof(capacity)='integer' AND capacity BETWEEN 1 AND 100),buffer_before INTEGER NOT NULL CHECK(typeof(buffer_before)='integer' AND buffer_before BETWEEN 0 AND 1440),buffer_after INTEGER NOT NULL CHECK(typeof(buffer_after)='integer' AND buffer_after BETWEEN 0 AND 1440),status TEXT NOT NULL CHECK(status IN('active','inactive')),source_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(resource_id,version),UNIQUE(store_id,sequence),FOREIGN KEY(resource_id,store_id) REFERENCES schedule_resources(id,store_id));
CREATE TABLE schedule_slots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>0),slot_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,store_id));
CREATE TABLE schedule_slot_events(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL,store_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('create','revise','cancel')),status TEXT NOT NULL CHECK(status IN('active','cancelled')),kind TEXT NOT NULL CHECK(kind IN('one','group','maintenance')),capacity INTEGER NOT NULL CHECK(typeof(capacity)='integer' AND capacity BETWEEN 0 AND 100),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,resources_json TEXT NOT NULL CHECK(json_valid(resources_json)),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(slot_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(slot_id,store_id) REFERENCES schedule_slots(id,store_id),CHECK(ends_at>starts_at),CHECK((kind='one' AND capacity=1) OR (kind='group' AND capacity BETWEEN 1 AND 100) OR (kind='maintenance' AND capacity=0)));
CREATE TABLE schedule_bookings(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),plan_id TEXT NOT NULL,plan_version INTEGER NOT NULL,cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,serial INTEGER NOT NULL CHECK(serial>0),booking_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,store_id),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version));
CREATE TABLE schedule_booking_events(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL,store_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('create','promote','move','cancel','leave')),status TEXT NOT NULL CHECK(status IN('booked','waiting','cancelled')),slot_id TEXT NOT NULL,slot_revision INTEGER NOT NULL,plan_revision INTEGER NOT NULL,queue_sequence INTEGER,previous_event_id TEXT REFERENCES schedule_booking_events(id),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(booking_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(booking_id,store_id) REFERENCES schedule_bookings(id,store_id),FOREIGN KEY(slot_id,slot_revision) REFERENCES schedule_slot_events(slot_id,revision),CHECK((status='waiting' AND queue_sequence IS NOT NULL) OR (status!='waiting' AND queue_sequence IS NULL)));
CREATE VIEW schedule_journal AS SELECT store_id,sequence,created_at,'resources' kind,resource_id root_id,version revision FROM schedule_resource_versions UNION ALL SELECT store_id,sequence,created_at,'slots',slot_id,revision FROM schedule_slot_events UNION ALL SELECT store_id,sequence,created_at,'bookings',booking_id,revision FROM schedule_booking_events;
CREATE VIEW schedule_current_resources AS SELECT v.*,r.kind,r.user_id,r.code FROM schedule_resource_versions v JOIN schedule_resources r ON r.id=v.resource_id WHERE v.version=(SELECT max(version) FROM schedule_resource_versions WHERE resource_id=v.resource_id);
CREATE VIEW schedule_current_slots AS SELECT * FROM schedule_slot_events e WHERE e.revision=(SELECT max(revision) FROM schedule_slot_events WHERE slot_id=e.slot_id);
CREATE VIEW schedule_current_bookings AS SELECT e.*,b.customer_id,b.plan_id,b.plan_version FROM schedule_booking_events e JOIN schedule_bookings b ON b.id=e.booking_id WHERE e.revision=(SELECT max(revision) FROM schedule_booking_events WHERE booking_id=e.booking_id);
CREATE INDEX schedule_bookings_customer ON schedule_bookings(customer_id,serial);
CREATE TRIGGER schedule_resources_actor BEFORE INSERT ON schedule_resources WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_resources_no_update BEFORE UPDATE ON schedule_resources BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_resources_no_delete BEFORE DELETE ON schedule_resources BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_resource_versions_actor BEFORE INSERT ON schedule_resource_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_resource_versions_no_update BEFORE UPDATE ON schedule_resource_versions BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_resource_versions_no_delete BEFORE DELETE ON schedule_resource_versions BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_slots_actor BEFORE INSERT ON schedule_slots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_slots_no_update BEFORE UPDATE ON schedule_slots BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_slots_no_delete BEFORE DELETE ON schedule_slots BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_slot_events_actor BEFORE INSERT ON schedule_slot_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_slot_events_no_update BEFORE UPDATE ON schedule_slot_events BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_slot_events_no_delete BEFORE DELETE ON schedule_slot_events BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_bookings_actor BEFORE INSERT ON schedule_bookings WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_bookings_no_update BEFORE UPDATE ON schedule_bookings BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_bookings_no_delete BEFORE DELETE ON schedule_bookings BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_booking_events_actor BEFORE INSERT ON schedule_booking_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND COALESCE(x.must_change_password,0)=0) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') BEGIN SELECT RAISE(ABORT,'schedule actor or time mismatch'); END;
CREATE TRIGGER schedule_booking_events_no_update BEFORE UPDATE ON schedule_booking_events BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_booking_events_no_delete BEFORE DELETE ON schedule_booking_events BEGIN SELECT RAISE(ABORT,'immutable schedule history'); END;
CREATE TRIGGER schedule_resource_versions_sequence BEFORE INSERT ON schedule_resource_versions WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM schedule_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM schedule_journal WHERE store_id=NEW.store_id),NEW.created_at) OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 BEGIN SELECT RAISE(ABORT,'schedule journal mismatch'); END;
CREATE TRIGGER schedule_slot_events_sequence BEFORE INSERT ON schedule_slot_events WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM schedule_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM schedule_journal WHERE store_id=NEW.store_id),NEW.created_at) OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 BEGIN SELECT RAISE(ABORT,'schedule journal mismatch'); END;
CREATE TRIGGER schedule_booking_events_sequence BEFORE INSERT ON schedule_booking_events WHEN NEW.sequence!=(SELECT COALESCE(max(sequence),0)+1 FROM schedule_journal WHERE store_id=NEW.store_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM schedule_journal WHERE store_id=NEW.store_id),NEW.created_at) OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 BEGIN SELECT RAISE(ABORT,'schedule journal mismatch'); END;
CREATE TRIGGER schedule_resource_guard BEFORE INSERT ON schedule_resources WHEN length(trim(NEW.code)) NOT BETWEEN 1 AND 60 OR (NEW.user_id IS NOT NULL AND (EXISTS(SELECT 1 FROM schedule_resources WHERE user_id=NEW.user_id) OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.user_id AND u.store_id=NEW.store_id AND u.active=1 AND u.role='professional' AND COALESCE(x.must_change_password,0)=0))) BEGIN SELECT RAISE(ABORT,'schedule resource source mismatch'); END;
CREATE TRIGGER schedule_resource_version_guard BEFORE INSERT ON schedule_resource_versions WHEN NEW.version!=(SELECT COALESCE(max(version),0)+1 FROM schedule_resource_versions WHERE resource_id=NEW.resource_id) OR length(trim(NEW.name)) NOT BETWEEN 1 AND 120 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 1000 OR (NEW.version=1 AND NOT EXISTS(SELECT 1 FROM schedule_resources WHERE id=NEW.resource_id AND created_at=NEW.created_at AND created_by=NEW.created_by)) BEGIN SELECT RAISE(ABORT,'schedule resource version mismatch'); END;
CREATE TRIGGER schedule_slot_root_guard BEFORE INSERT ON schedule_slots WHEN NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM schedule_slots WHERE store_id=NEW.store_id) OR NEW.slot_number!=('SL-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) BEGIN SELECT RAISE(ABORT,'schedule slot identity mismatch'); END;
CREATE TRIGGER schedule_booking_root_guard BEFORE INSERT ON schedule_bookings WHEN NEW.serial!=(SELECT COALESCE(max(serial),0)+1 FROM schedule_bookings WHERE store_id=NEW.store_id) OR NEW.booking_number!=('BK-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial)) OR NOT EXISTS(SELECT 1 FROM training_plans p JOIN training_plan_versions v ON v.plan_id=p.id JOIN customers c ON c.id=p.customer_id WHERE p.id=NEW.plan_id AND v.version=NEW.plan_version AND p.customer_id=NEW.customer_id AND c.store_id=NEW.store_id AND p.store_id=NEW.store_id AND p.cycle_id=NEW.cycle_id AND p.cycle_version=NEW.cycle_version AND v.created_at<=NEW.created_at) BEGIN SELECT RAISE(ABORT,'schedule booking source mismatch'); END;
CREATE TRIGGER schedule_slot_guard BEFORE INSERT ON schedule_slot_events WHEN NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM schedule_slot_events WHERE slot_id=NEW.slot_id) OR length(NEW.starts_at)!=24 OR length(NEW.ends_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.starts_at) IS NOT NEW.starts_at OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.ends_at) IS NOT NEW.ends_at OR length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR (NEW.revision=1 AND (NEW.action!='create' OR NEW.status!='active' OR NOT EXISTS(SELECT 1 FROM schedule_slots WHERE id=NEW.slot_id AND created_at=NEW.created_at AND created_by=NEW.created_by))) OR (NEW.revision>1 AND (NEW.action='create' OR NOT EXISTS(SELECT 1 FROM schedule_current_slots WHERE slot_id=NEW.slot_id AND status='active') OR EXISTS(SELECT 1 FROM schedule_current_bookings WHERE slot_id=NEW.slot_id AND status!='cancelled'))) OR (NEW.status='cancelled')!=(NEW.action='cancel') OR (NEW.kind='maintenance' AND (SELECT role FROM users WHERE id=NEW.created_by)!='manager') OR json_type(NEW.resources_json)!='array' OR json_array_length(NEW.resources_json) NOT BETWEEN 1 AND 10 OR EXISTS(SELECT 1 FROM json_each(NEW.resources_json) j WHERE json_type(j.value)!='object' OR (SELECT count(*) FROM json_each(j.value))!=2 OR json_type(j.value,'$.id') IS NOT 'text' OR json_type(j.value,'$.version') IS NOT 'integer') OR (SELECT count(DISTINCT json_extract(value,'$.id')) FROM json_each(NEW.resources_json))!=json_array_length(NEW.resources_json) BEGIN SELECT RAISE(ABORT,'schedule slot transition mismatch'); END;
CREATE TRIGGER schedule_slot_resources BEFORE INSERT ON schedule_slot_events WHEN NEW.action!='cancel' AND (EXISTS(SELECT 1 FROM json_each(NEW.resources_json) j LEFT JOIN schedule_current_resources r ON r.resource_id=json_extract(j.value,'$.id') AND r.version=json_extract(j.value,'$.version') WHERE r.resource_id IS NULL OR r.store_id!=NEW.store_id OR r.status!='active' OR r.capacity<NEW.capacity OR (r.kind='staff' AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=r.user_id AND u.store_id=NEW.store_id AND u.active=1 AND u.role='professional' AND COALESCE(x.must_change_password,0)=0))) OR (NEW.kind!='maintenance' AND ((SELECT count(*) FROM json_each(NEW.resources_json) j JOIN schedule_resources r ON r.id=json_extract(j.value,'$.id') WHERE r.kind='staff')!=1 OR NOT EXISTS(SELECT 1 FROM json_each(NEW.resources_json) j JOIN schedule_resources r ON r.id=json_extract(j.value,'$.id') WHERE r.kind='room'))) OR EXISTS(SELECT 1 FROM schedule_current_slots e JOIN json_each(e.resources_json) old JOIN schedule_resource_versions ov ON ov.resource_id=json_extract(old.value,'$.id') AND ov.version=json_extract(old.value,'$.version') JOIN json_each(NEW.resources_json) fresh ON json_extract(fresh.value,'$.id')=ov.resource_id JOIN schedule_resource_versions nv ON nv.resource_id=ov.resource_id AND nv.version=json_extract(fresh.value,'$.version') WHERE e.store_id=NEW.store_id AND e.slot_id!=NEW.slot_id AND e.status='active' AND unixepoch(NEW.starts_at,'subsec')-nv.buffer_before*60<unixepoch(e.ends_at,'subsec')+ov.buffer_after*60 AND unixepoch(e.starts_at,'subsec')-ov.buffer_before*60<unixepoch(NEW.ends_at,'subsec')+nv.buffer_after*60)) BEGIN SELECT RAISE(ABORT,'schedule resource conflict'); END;
CREATE TRIGGER schedule_slot_cancel_snapshot BEFORE INSERT ON schedule_slot_events WHEN NEW.action='cancel' AND NOT EXISTS(SELECT 1 FROM schedule_current_slots WHERE slot_id=NEW.slot_id AND kind=NEW.kind AND capacity=NEW.capacity AND starts_at=NEW.starts_at AND ends_at=NEW.ends_at AND resources_json=NEW.resources_json) BEGIN SELECT RAISE(ABORT,'schedule cancellation changed source'); END;
CREATE TRIGGER schedule_booking_guard BEFORE INSERT ON schedule_booking_events WHEN NEW.revision!=(SELECT COALESCE(max(revision),0)+1 FROM schedule_booking_events WHERE booking_id=NEW.booking_id) OR length(trim(NEW.note)) NOT BETWEEN 1 AND 1000 OR NEW.previous_event_id IS NOT (SELECT id FROM schedule_current_bookings WHERE booking_id=NEW.booking_id) OR (NEW.revision=1 AND (NEW.action!='create' OR NEW.status='cancelled' OR NOT EXISTS(SELECT 1 FROM schedule_bookings WHERE id=NEW.booking_id AND created_at=NEW.created_at AND created_by=NEW.created_by))) OR (NEW.revision>1 AND (NEW.action='create' OR NOT EXISTS(SELECT 1 FROM schedule_current_bookings p WHERE p.booking_id=NEW.booking_id AND p.status!='cancelled' AND ((NEW.action='promote' AND p.status='waiting' AND NEW.status='booked' AND p.slot_id=NEW.slot_id) OR (NEW.action='move' AND p.status=NEW.status AND p.slot_id!=NEW.slot_id) OR (NEW.action='cancel' AND NEW.status='cancelled' AND p.slot_id=NEW.slot_id) OR (NEW.action='leave' AND NEW.status='cancelled' AND p.status='booked' AND p.slot_id=NEW.slot_id))))) OR (NEW.status='waiting' AND NEW.queue_sequence!=NEW.sequence) BEGIN SELECT RAISE(ABORT,'schedule booking transition mismatch'); END;
CREATE TRIGGER schedule_booking_admit BEFORE INSERT ON schedule_booking_events WHEN NEW.status!='cancelled' AND (NOT EXISTS(SELECT 1 FROM schedule_current_slots s WHERE s.slot_id=NEW.slot_id AND s.revision=NEW.slot_revision AND s.store_id=NEW.store_id AND s.status='active' AND s.kind!='maintenance') OR EXISTS(SELECT 1 FROM schedule_current_slots s JOIN json_each(s.resources_json) j LEFT JOIN schedule_current_resources r ON r.resource_id=json_extract(j.value,'$.id') AND r.version=json_extract(j.value,'$.version') WHERE s.slot_id=NEW.slot_id AND (r.resource_id IS NULL OR r.status!='active' OR (r.kind='staff' AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=r.user_id AND u.store_id=NEW.store_id AND u.active=1 AND u.role='professional' AND COALESCE(x.must_change_password,0)=0)))) OR NOT EXISTS(SELECT 1 FROM schedule_bookings b JOIN training_plan_events p ON p.plan_id=b.plan_id WHERE b.id=NEW.booking_id AND p.revision=NEW.plan_revision AND p.plan_version=b.plan_version AND p.status='active' AND p.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=b.plan_id)) OR EXISTS(SELECT 1 FROM schedule_current_bookings b JOIN schedule_bookings mine ON mine.id=NEW.booking_id JOIN schedule_current_slots s ON s.slot_id=b.slot_id JOIN schedule_current_slots dest ON dest.slot_id=NEW.slot_id WHERE b.booking_id!=NEW.booking_id AND b.customer_id=mine.customer_id AND b.status!='cancelled' AND (b.slot_id=NEW.slot_id OR (NEW.status='booked' AND b.status='booked' AND s.starts_at<dest.ends_at AND dest.starts_at<s.ends_at))) OR (NEW.status='booked' AND (SELECT count(*) FROM schedule_current_bookings WHERE slot_id=NEW.slot_id AND status='booked' AND booking_id!=NEW.booking_id)>=(SELECT capacity FROM schedule_current_slots WHERE slot_id=NEW.slot_id))) BEGIN SELECT RAISE(ABORT,'schedule admission or capacity conflict'); END;
CREATE TRIGGER schedule_booking_cancel_snapshot BEFORE INSERT ON schedule_booking_events WHEN NEW.status='cancelled' AND NOT EXISTS(SELECT 1 FROM schedule_current_bookings WHERE booking_id=NEW.booking_id AND slot_id=NEW.slot_id AND slot_revision=NEW.slot_revision AND plan_revision=NEW.plan_revision) BEGIN SELECT RAISE(ABORT,'schedule cancellation changed source'); END;
